# Auto-generated by refactor: extracted verbatim from starter.py (factory + blueprints split).
# LP15-C: the canonical acquisition/analysis bodies now live in
# app/services/menu_analysis.py (shared with the native /api/v1 route); these
# views only parse the browser request and render the historical web answers,
# pinned by tests/test_menu_web_characterization.py.
import json
from flask import Blueprint, jsonify, request
from flask_login import current_user
from app.auth_middleware import require_auth

from app.config import AI_RATELIMIT, BEDROCK_RATELIMIT, SCRAPE_RATELIMIT
from app.extensions import _user_or_ip_key, limiter
from app.i18n import t
from app.services import menu_analysis
from app.services.ai_gate import ai_concurrency_gate, scrape_concurrency_gate


# Remote menu response content must never be interpolated into server logs.
# Use counts, fixed reason codes, exception types and redacted request URLs only.
bp = Blueprint("menu", __name__)


def _web_scan_failure(error):
    reason, detail = error.reason, error.detail
    if reason == "URL_INVALID":
        return jsonify({"error": detail}), 400
    if reason == "DRIVE":
        try:
            err_payload = json.loads(detail)
            return jsonify(err_payload), 403
        except (json.JSONDecodeError, TypeError):
            return jsonify({"error": detail}), 422
    if reason == "FETCH_REJECTED":
        status = 415 if detail in {"MENU_MEDIA_UNSUPPORTED", "MENU_ENCODING_UNSUPPORTED"} else 400
        return jsonify({"error": detail}), status
    if reason == "TIMEOUT":
        return jsonify({"error": t("route.menu.timeout")}), 504
    if reason == "CONNECTION":
        return jsonify({"error": t("route.menu.conn_error", err=detail)}), 502
    if reason == "UNSUPPORTED_TYPE":
        return jsonify({"error": t("route.menu.unsupported_type")}), 415
    if reason == "PARSE_LIMIT":
        return jsonify({"error": detail}), 422
    return jsonify({"error": t("route.menu.unreadable")}), 422


@bp.route("/api/proxy/scan-menu", methods=["POST"])
@require_auth
@limiter.limit(SCRAPE_RATELIMIT, key_func=_user_or_ip_key)
@scrape_concurrency_gate  # INF-5: ağ-bağımlı scrape AYRI semaforda — LLM slotlarını tutmasın
def proxy_scan_menu():
    data = request.get_json(silent=True) or {}
    url = (data or {}).get("url", "").strip()
    if not url:
        return jsonify({"error": t("route.url_required")}), 400

    # One call = one LP15-B1 operation budget (acquire_menu is @menu_operation).
    try:
        return jsonify(menu_analysis.acquire_menu(url))
    except menu_analysis.MenuAcquisitionError as error:
        return _web_scan_failure(error)


@bp.route("/api/menu/analyze", methods=["POST"])
@require_auth
@limiter.limit(AI_RATELIMIT, key_func=_user_or_ip_key)
@limiter.limit(BEDROCK_RATELIMIT, key_func=_user_or_ip_key)  # Sonnet (çoklu çağrı): daha sıkı tavan
@ai_concurrency_gate  # A1: bloklayıcı AI çağrıları tüm thread'leri doldurmasın
def analyze_menu():
    data = request.get_json(silent=True) or {}
    raw_text = (data or {}).get("menu_text", "").strip()
    fw_state = (data or {}).get("framework_state")
    menu_source = (data or {}).get("menu_source", "web_scraper")
    headings_hint = (data or {}).get("headings")

    try:
        analysis = menu_analysis.analyze_menu_text(
            current_user.id, raw_text, fw_state, menu_source, headings_hint)
    except menu_analysis.MenuAnalysisError as error:
        if error.reason == "EMPTY_MENU_TEXT":
            return jsonify({
                "success": False,
                "error": "EMPTY_MENU_TEXT",
                "message": t("route.menu.empty_text"),
                "items": [], "categories": {},
            }), 400
        if error.reason == "PROFILE_DATA_MISSING":
            return jsonify({"error": t("route.profile_data_missing")}), 400
        return jsonify({"success": False, "error": "OUTPUT_PARSING_FAILED",
                        "message": t("route.menu.parse_failed"),
                        "items": [], "categories": {}}), 422
    return jsonify(menu_analysis.web_analysis_payload(analysis))
